package org.apache.commons.lang3.text.translate;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.StringWriter;
import java.io.IOException;

public class AgentBRT_Lang_28_raw_diff_Test {

    @Test
    public void testReproduceBug() throws IOException {
        NumericEntityUnescaper unescaper = new NumericEntityUnescaper();
        StringWriter writer = new StringWriter();
        String input = "&#x1F600;"; // Grinning face emoji, code point 0x1F600

        int result = unescaper.translate(input, 0, writer);

        // The expected output should be the surrogate pair for the grinning face emoji
        String expectedOutput = new String(Character.toChars(0x1F600));

        assertEquals("The translation did not produce the expected surrogate pair.", expectedOutput, writer.toString());
        assertEquals("The return value should indicate the number of characters consumed.", input.length(), result);
    }
}

